#!/usr/bin/env python3
"""compute-entity-similarity.py - Semantic similarity for entity linking.

Computes similarity between entities using Levenshtein distance + keyword
overlap. Used by memory-evolution.sh to infer relations in the ontology graph.

Usage:
  compute-entity-similarity.py --graph FILE --entity-id ID [--threshold 0.75] [--max-relations 3]

Outputs JSON array of related entities with similarity scores.
"""

import argparse
import json
import os
import re
import sys
from collections import Counter


def load_graph(filepath):
    """Load entities from graph.jsonl."""
    entities = {}
    if not os.path.isfile(filepath):
        return entities
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if record.get("type") == "relation":
                continue
            eid = record.get("id", "")
            if eid:
                entities[eid] = record
    return entities


def tokenize(text):
    """Extract meaningful tokens from text."""
    if not isinstance(text, str):
        return []
    # Lowercase, split on non-alphanumeric, filter short tokens
    tokens = re.findall(r'[a-z0-9]+', text.lower())
    return [t for t in tokens if len(t) > 2]


def extract_text(entity):
    """Extract all searchable text from an entity."""
    parts = []
    props = entity.get("properties", {})
    if isinstance(props, dict):
        for key, val in props.items():
            parts.append(str(key))
            if isinstance(val, str):
                parts.append(val)
            elif isinstance(val, list):
                parts.extend(str(v) for v in val)
    # Also include entity type and name
    if entity.get("entity_type"):
        parts.append(str(entity["entity_type"]))
    if props.get("name"):
        parts.append(str(props["name"]))
    if props.get("description"):
        parts.append(str(props["description"]))
    if props.get("title"):
        parts.append(str(props["title"]))
    return " ".join(parts)


def levenshtein_ratio(s1, s2):
    """Compute Levenshtein similarity ratio (0.0 to 1.0)."""
    if not s1 or not s2:
        return 0.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 and len2 == 0:
        return 1.0

    # Use iterative matrix (memory efficient for shorter strings)
    if len1 > 500 or len2 > 500:
        # For very long strings, fall back to token overlap only
        return 0.0

    prev = list(range(len2 + 1))
    for i in range(1, len1 + 1):
        curr = [i] + [0] * len2
        for j in range(1, len2 + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            curr[j] = min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost)
        prev = curr

    distance = prev[len2]
    max_len = max(len1, len2)
    return 1.0 - (distance / max_len)


def keyword_overlap(tokens1, tokens2):
    """Compute Jaccard-like keyword overlap score (0.0 to 1.0)."""
    if not tokens1 or not tokens2:
        return 0.0
    set1 = set(tokens1)
    set2 = set(tokens2)
    intersection = set1 & set2
    union = set1 | set2
    if not union:
        return 0.0
    return len(intersection) / len(union)


def compute_similarity(entity_a, entity_b):
    """Compute combined similarity score between two entities."""
    text_a = extract_text(entity_a)
    text_b = extract_text(entity_b)

    tokens_a = tokenize(text_a)
    tokens_b = tokenize(text_b)

    # Keyword overlap (weighted 0.6)
    kw_score = keyword_overlap(tokens_a, tokens_b)

    # Levenshtein on extracted text (weighted 0.4, capped at 200 chars)
    lev_score = levenshtein_ratio(text_a[:200].lower(), text_b[:200].lower())

    combined = 0.6 * kw_score + 0.4 * lev_score

    # Build reasoning
    common = set(tokens_a) & set(tokens_b)
    reasoning = f"keyword_overlap={kw_score:.3f}, levenshtein={lev_score:.3f}"
    if common:
        reasoning += f", shared_keywords=[{','.join(sorted(common)[:5])}]"

    return combined, reasoning


def find_similar(graph, target_id, threshold=0.75, max_relations=3):
    """Find entities similar to target."""
    if target_id not in graph:
        print(f"ERROR: Entity {target_id} not found in graph", file=sys.stderr)
        sys.exit(1)

    target = graph[target_id]
    scores = []

    for eid, entity in graph.items():
        if eid == target_id:
            continue
        score, reasoning = compute_similarity(target, entity)
        if score >= threshold:
            scores.append({
                "entity_id": eid,
                "entity_type": entity.get("entity_type", "unknown"),
                "similarity_score": round(score, 4),
                "reasoning": reasoning
            })

    # Sort by score descending, take top N
    scores.sort(key=lambda x: x["similarity_score"], reverse=True)
    return scores[:max_relations]


def main():
    parser = argparse.ArgumentParser(
        description="Compute entity similarity for relation inference"
    )
    parser.add_argument("--graph", required=True, help="Path to graph.jsonl")
    parser.add_argument("--entity-id", required=True, help="Target entity ID")
    parser.add_argument("--threshold", type=float, default=0.75, help="Similarity threshold (default: 0.75)")
    parser.add_argument("--max-relations", type=int, default=3, help="Max relations to infer (default: 3)")
    args = parser.parse_args()

    graph = load_graph(args.graph)
    if not graph:
        print("[]")
        sys.exit(0)

    results = find_similar(graph, args.entity_id, args.threshold, args.max_relations)
    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""detect-contract-conflicts.py — Cross-skill ontology conflict detection.

Scans all skills in the skills directory for ontologyContract declarations,
then detects incompatible postconditions across skills.

Conflict types:
- Equality vs inequality: Skill A says "X.p == v" and Skill B says "X.p != v"
- Contradictory equality: Skill A says "X.p == v1" and Skill B says "X.p == v2" (v1 != v2)

Called by detect-contract-conflicts.sh via environment variables:
  _SKILLS_DIR    Path to skills directory
  _JSON_OUTPUT   'true' for JSON output
"""

import json
import os
import re
import sys
from collections import defaultdict


def load_all_contracts(skills_dir):
    """Load ontologyContract from all skill.json files in skills_dir."""
    contracts = {}

    if not os.path.isdir(skills_dir):
        return contracts

    for entry in sorted(os.listdir(skills_dir)):
        skill_json = os.path.join(skills_dir, entry, "skill.json")
        if not os.path.isfile(skill_json):
            continue

        try:
            with open(skill_json) as f:
                data = json.load(f)
        except (json.JSONDecodeError, IOError):
            continue

        contract = data.get("ontologyContract")
        if contract and contract.get("ontology"):
            contracts[entry] = contract

    return contracts


def parse_postcondition(postcond):
    """Parse a postcondition into structured form.

    Returns dict with: entity_type, property, operator, value
    or None if unparseable.
    """
    parts = postcond.split(".", 1)
    if len(parts) != 2:
        return None

    etype = parts[0]
    rest = parts[1]

    if " == " in rest:
        prop, value = rest.split(" == ", 1)
        return {
            "entity_type": etype,
            "property": prop.strip(),
            "operator": "==",
            "value": value.strip().strip("'\""),
        }
    elif " != " in rest:
        prop, value = rest.split(" != ", 1)
        return {
            "entity_type": etype,
            "property": prop.strip(),
            "operator": "!=",
            "value": value.strip().strip("'\""),
        }
    elif " is valid enum" in rest:
        prop = rest.replace(" is valid enum", "").strip()
        return {
            "entity_type": etype,
            "property": prop,
            "operator": "is_valid_enum",
            "value": None,
        }
    elif " exists" in rest:
        prop = rest.replace(" exists", "").strip()
        return {
            "entity_type": etype,
            "property": prop,
            "operator": "exists",
            "value": None,
        }

    return None


def detect_conflicts(contracts):
    """Detect conflicting postconditions across skills.

    Returns list of conflict dicts.
    """
    # Group postconditions by (entity_type, property)
    postconds_by_field = defaultdict(list)

    for skill_name, contract in contracts.items():
        ontology = contract.get("ontology", {})
        for postcond in ontology.get("postconditions", []):
            parsed = parse_postcondition(postcond)
            if parsed:
                key = (parsed["entity_type"], parsed["property"])
                postconds_by_field[key].append({
                    "skill": skill_name,
                    "raw": postcond,
                    "parsed": parsed,
                })

    conflicts = []

    for field_key, entries in postconds_by_field.items():
        if len(entries) < 2:
            continue

        # Check all pairs for conflicts
        for i in range(len(entries)):
            for j in range(i + 1, len(entries)):
                a = entries[i]
                b = entries[j]
                pa = a["parsed"]
                pb = b["parsed"]

                conflict = None

                # Case 1: A says == v, B says != v (same value)
                if pa["operator"] == "==" and pb["operator"] == "!=" and pa["value"] == pb["value"]:
                    conflict = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{a['skill']} requires {pa['entity_type']}.{pa['property']} == '{pa['value']}' "
                            f"but {b['skill']} forbids it (!= '{pb['value']}')"
                        ),
                    }
                elif pa["operator"] == "!=" and pb["operator"] == "==" and pa["value"] == pb["value"]:
                    conflict = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{b['skill']} requires {pb['entity_type']}.{pb['property']} == '{pb['value']}' "
                            f"but {a['skill']} forbids it (!= '{pa['value']}')"
                        ),
                    }

                # Case 2: A says == v1, B says == v2 (different values)
                elif pa["operator"] == "==" and pb["operator"] == "==" and pa["value"] != pb["value"]:
                    conflict = {
                        "type": "contradictory_equality",
                        "description": (
                            f"{a['skill']} requires {pa['entity_type']}.{pa['property']} == '{pa['value']}' "
                            f"but {b['skill']} requires == '{pb['value']}'"
                        ),
                    }

                if conflict:
                    conflict["skill_a"] = a["skill"]
                    conflict["skill_b"] = b["skill"]
                    conflict["postcondition_a"] = a["raw"]
                    conflict["postcondition_b"] = b["raw"]
                    conflict["field"] = f"{pa['entity_type']}.{pa['property']}"
                    conflicts.append(conflict)

    return conflicts


def main():
    skills_dir = os.path.expanduser(os.environ.get("_SKILLS_DIR", "~/.openclaw/skills"))
    json_output = os.environ.get("_JSON_OUTPUT", "false") == "true"

    contracts = load_all_contracts(skills_dir)

    if not contracts:
        result = {"conflicts": [], "skills_checked": 0, "message": "no skills with ontology contracts found"}
        if json_output:
            print(json.dumps(result, indent=2))
        else:
            print("No skills with ontology contracts found")
        sys.exit(0)

    conflicts = detect_conflicts(contracts)

    # Check reads/writes compatibility (informational, not a conflict)
    compatible_pairs = []
    for name_a, contract_a in contracts.items():
        for name_b, contract_b in contracts.items():
            if name_a >= name_b:
                continue
            writes_a = set(contract_a.get("ontology", {}).get("writes", []))
            reads_b = set(contract_b.get("ontology", {}).get("reads", []))
            writes_b = set(contract_b.get("ontology", {}).get("writes", []))
            reads_a = set(contract_a.get("ontology", {}).get("reads", []))

            shared = (writes_a & reads_b) | (writes_b & reads_a)
            if shared:
                compatible_pairs.append({
                    "skill_a": name_a,
                    "skill_b": name_b,
                    "shared_types": sorted(shared),
                })

    result = {
        "conflicts": conflicts,
        "conflicts_found": len(conflicts),
        "skills_checked": len(contracts),
        "skills": sorted(contracts.keys()),
        "compatible_pairs": compatible_pairs,
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Checked {len(contracts)} skill(s): {', '.join(sorted(contracts.keys()))}")
        print()

        if conflicts:
            print(f"CONFLICTS FOUND: {len(conflicts)}")
            for c in conflicts:
                print(f"  * [{c['type']}] {c['description']}")
                print(f"    {c['skill_a']}: {c['postcondition_a']}")
                print(f"    {c['skill_b']}: {c['postcondition_b']}")
                print()
        else:
            print("No conflicts detected")

        if compatible_pairs:
            print()
            print("Compatible read/write pairs:")
            for pair in compatible_pairs:
                print(f"  {pair['skill_a']} <-> {pair['skill_b']}: {', '.join(pair['shared_types'])}")

    sys.exit(1 if conflicts else 0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""detect-failure.py - Self-detect trigger for auto-capturing Problems.

Scans agent text for failure patterns, auto-creates Problems via learning.py.
Debounces duplicates within configurable window.

Usage:
  detect-failure.py --input <file_or_stdin>
  detect-failure.py --scan-sessions
  echo "ERROR 401 Unauthorized" | detect-failure.py --input -

Environment:
  CONFIG_FILE, LEARNING_DIR, SESSION_DIR (all overridable)
"""
import argparse, json, os, re, subprocess, sys
from datetime import datetime, timezone, timedelta
from pathlib import Path

CONFIG_FILE = os.environ.get("CONFIG_FILE", os.path.expanduser("~/.amcp/config.json"))

def _get_workspace():
    try:
        with open(os.path.expanduser("~/.openclaw/openclaw.json")) as f:
            return os.path.expanduser(json.load(f).get("agents",{}).get("defaults",{}).get("workspace","~/.openclaw/workspace"))
    except (IOError, json.JSONDecodeError):
        return os.path.expanduser("~/.openclaw/workspace")

def _get_dir(env_key, fallback):
    v = os.environ.get(env_key)
    return os.path.expanduser(v) if v else fallback

LEARNING_DIR = _get_dir("LEARNING_DIR", os.path.join(_get_workspace(), "memory", "learning"))
SESSION_DIR = _get_dir("SESSION_DIR", os.path.expanduser("~/.openclaw/agents/main/sessions"))
DETECTIONS_LOG = os.path.join(LEARNING_DIR, "detections.log")

def load_config():
    defaults = {"enabled": True, "debounceHours": 24}
    try:
        with open(CONFIG_FILE) as f:
            sd = json.load(f).get("learning",{}).get("selfDetect",{})
        return {"enabled": sd.get("enabled", True), "debounceHours": sd.get("debounceHours", 24)}
    except (IOError, json.JSONDecodeError):
        return defaults

# Failure patterns: (compiled_regex, category, extract_fn)
FAILURE_PATTERNS = [
    (re.compile(r"\b(HTTP[/ ]?)?([45]\d{2})\b.*?(Unauthorized|Forbidden|Not Found|Internal Server Error|Bad Gateway|Service Unavailable)", re.I),
     "api_error", lambda m: f"HTTP {m.group(2)} {m.group(3)}"),
    (re.compile(r"\b(?:status[_ ]?code|HTTP|error)[:\s=]+([45]\d{2})\b", re.I),
     "api_error", lambda m: f"HTTP {m.group(1)} error"),
    (re.compile(r"I\s+don'?t\s+know\s+how\s+to\b(.{0,80})", re.I),
     "knowledge_gap", lambda m: f"Agent doesn't know how to {m.group(1).strip()}"),
    (re.compile(r"I\s+need\s+help\s+with\b(.{0,80})", re.I),
     "knowledge_gap", lambda m: f"Agent needs help with {m.group(1).strip()}"),
    (re.compile(r"I'?m\s+(?:not\s+sure|unable\s+to|struggling\s+to)\b(.{0,80})", re.I),
     "knowledge_gap", lambda m: f"Agent uncertain: {m.group(1).strip()}"),
    (re.compile(r"(?:FATAL|CRITICAL|ERROR):\s*(.{5,120})", re.I),
     "error_signal", lambda m: m.group(0).strip()[:120]),
    (re.compile(r"(?:authentication|auth|token|api.?key)\s+(?:failed|expired|invalid|rejected|revoked)", re.I),
     "auth_failure", lambda m: m.group(0).strip()[:120]),
]

def scan_text(text):
    """Scan text for failure patterns. Returns list of detections."""
    detections, seen = [], set()
    for regex, cat, extract in FAILURE_PATTERNS:
        if cat in seen:
            continue
        match = regex.search(text)
        if match:
            seen.add(cat)
            desc = extract(match).rstrip(" .,;:")
            detections.append({"category": cat, "description": desc, "matched_text": match.group(0)[:200]})
    return detections

def is_debounced(description, debounce_hours):
    """Check if similar self-detect problem exists within debounce window."""
    problems_file = os.path.join(LEARNING_DIR, "problems.jsonl")
    if not os.path.isfile(problems_file):
        return False
    cutoff = datetime.now(timezone.utc) - timedelta(hours=debounce_hours)
    desc_tokens = set(re.findall(r'\b\w{3,}\b', description.lower()))
    if not desc_tokens:
        return False
    with open(problems_file) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if r.get("op") != "create" or r.get("source") != "self-detect":
                continue
            try:
                if datetime.fromisoformat(r.get("created","")) < cutoff:
                    continue
            except (ValueError, TypeError):
                continue
            existing_tokens = set(re.findall(r'\b\w{3,}\b', r.get("description","").lower()))
            if existing_tokens:
                overlap = len(desc_tokens & existing_tokens) / len(desc_tokens | existing_tokens)
                if overlap > 0.5:
                    return True
    return False

def log_detection(detection, problem_id, debounced):
    os.makedirs(os.path.dirname(DETECTIONS_LOG), exist_ok=True)
    entry = {"timestamp": datetime.now(timezone.utc).isoformat(), **{k: detection[k] for k in ("category","description","matched_text")}, "problem_id": problem_id, "debounced": debounced}
    with open(DETECTIONS_LOG, "a") as f:
        f.write(json.dumps(entry) + "\n")

def create_problem_via_cli(description):
    """Create a Problem using learning.py."""
    learning_py = os.path.join(os.path.dirname(os.path.abspath(__file__)), "learning.py")
    env = {**os.environ, "LEARNING_DIR": LEARNING_DIR}
    result = subprocess.run([sys.executable, learning_py, "problem", "create", "--description", description, "--source", "self-detect"], capture_output=True, text=True, env=env)
    if result.returncode == 0:
        try:
            return json.loads(result.stdout).get("id", "")
        except json.JSONDecodeError:
            return ""
    print(f"WARN: Failed to create problem: {result.stderr}", file=sys.stderr)
    return ""

def read_input(path):
    if path == "-":
        return sys.stdin.read()
    path = os.path.expanduser(path)
    if not os.path.isfile(path):
        print(f"ERROR: File not found: {path}", file=sys.stderr)
        sys.exit(1)
    with open(path) as f:
        return f.read()

def scan_recent_sessions():
    """Scan session transcripts modified in last 24h."""
    if not os.path.isdir(SESSION_DIR):
        return ""
    texts, now = [], datetime.now(timezone.utc)
    for entry in sorted(Path(SESSION_DIR).iterdir(), reverse=True):
        if not entry.is_file() or entry.suffix != ".jsonl":
            continue
        if (now - datetime.fromtimestamp(entry.stat().st_mtime, tz=timezone.utc)).total_seconds() > 86400:
            continue
        try:
            with open(entry) as f:
                for line in f:
                    line = line.strip()
                    if not line: continue
                    try:
                        c = json.loads(line).get("content","")
                        if isinstance(c, str): texts.append(c)
                    except json.JSONDecodeError: continue
        except IOError: continue
        if len(texts) > 5000: break
    return "\n".join(texts)

def main():
    parser = argparse.ArgumentParser(description="Detect failure patterns and auto-create Problems")
    parser.add_argument("--input", "-i", help="Input file (use - for stdin)")
    parser.add_argument("--scan-sessions", action="store_true", help="Scan recent session transcripts")
    parser.add_argument("--dry-run", action="store_true", help="Show detections without creating Problems")
    args = parser.parse_args()

    config = load_config()
    if not config["enabled"]:
        print("Self-detect disabled via config"); return

    if args.input:
        text = read_input(args.input)
    elif args.scan_sessions:
        text = scan_recent_sessions()
        if not text: print("No recent sessions to scan"); return
    else:
        parser.print_help(); sys.exit(1)

    detections = scan_text(text)
    if not detections:
        print("No failure patterns detected"); return

    debounce_hours = config["debounceHours"]
    created, debounced_count = 0, 0
    for det in detections:
        if is_debounced(det["description"], debounce_hours):
            debounced_count += 1
            log_detection(det, problem_id="", debounced=True)
            if not args.dry_run:
                print(f"  [DEBOUNCED] {det['category']}: {det['description']}")
            continue
        if args.dry_run:
            print(f"  [WOULD CREATE] {det['category']}: {det['description']}")
            log_detection(det, problem_id="dry-run", debounced=False)
            continue
        pid = create_problem_via_cli(det["description"])
        if pid:
            created += 1
            log_detection(det, problem_id=pid, debounced=False)
            print(f"  [CREATED] {pid}: {det['description']}")
        else:
            log_detection(det, problem_id="failed", debounced=False)
    print(f"\nDetections: {len(detections)}, Created: {created}, Debounced: {debounce_hours}h: {debounced_count}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
fix-openclaw-session.py — Repair corrupted OpenClaw session transcripts.

Fixes the "unexpected tool_use_id found in tool_result blocks" error that occurs
when an assistant response is aborted mid-tool_use, leaving orphaned tool_results
that the Anthropic API rejects on every subsequent turn.

Root cause: When stopReason is "error" or "aborted" and a tool_use block has
partialJson, the built-in transcript repair inserts synthetic toolResults, but
the API still rejects them because the original tool_use is structurally broken.

Usage:
    python3 fix-openclaw-session.py [--fix] [--verbose] [--all-agents] [session_dir]

    --fix        Apply the fix (default is dry-run)
    --verbose    Show detailed output
    --all-agents Scan all agents, not just main
    session_dir  Override session directory (default: ~/.openclaw/agents/main/sessions)
"""

import json
import os
import re
import sys
import shutil
from datetime import datetime
from pathlib import Path

DEFAULT_SESSION_DIR = os.path.expanduser("~/.openclaw/agents/main/sessions")


def find_active_session(session_dir):
    """Find the active session ID from sessions.json."""
    sessions_json = os.path.join(session_dir, "sessions.json")
    if not os.path.exists(sessions_json):
        return None
    with open(sessions_json) as f:
        data = json.load(f)
    for key, val in data.items():
        if isinstance(val, dict) and "sessionId" in val:
            return val["sessionId"]
    return None


def is_corrupted_error(msg):
    """Check if a message is a stopReason=error with tool_use_id rejection."""
    if msg.get("type") != "message":
        return False
    inner = msg.get("message", {})
    stop = inner.get("stopReason", "")
    err = inner.get("errorMessage", "")
    if stop == "error" and "unexpected `tool_use_id` found in `tool_result` blocks" in err:
        return True
    return False


def is_aborted_with_partial(msg):
    """Check if a message is an aborted/errored assistant with partialJson tool calls."""
    if msg.get("type") != "message":
        return False
    inner = msg.get("message", {})
    if inner.get("role") != "assistant":
        return False
    stop = inner.get("stopReason", "")
    if stop not in ("error", "aborted"):
        return False
    for block in inner.get("content", []):
        if block.get("type") == "toolCall" and "partialJson" in block:
            return True
    return False


def is_synthetic_tool_result(msg):
    """Check if a message is a synthetic toolResult inserted by openclaw repair."""
    if msg.get("type") != "message":
        return False
    inner = msg.get("message", {})
    if inner.get("role") != "toolResult":
        return False
    for block in inner.get("content", []):
        if isinstance(block, dict) and "synthetic error result for transcript repair" in block.get("text", ""):
            return True
    return False


def scan_session(filepath, verbose=False):
    """Scan a session file for corruption. Returns (remove_ids, reparent_map, details)."""
    with open(filepath) as f:
        lines = f.readlines()

    remove_ids = set()
    reparent_map = {}  # child_id -> new_parent_id
    details = []
    id_to_line = {}
    id_to_parent = {}
    id_to_obj = {}

    for i, line in enumerate(lines):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        msg_id = obj.get("id", "")
        parent_id = obj.get("parentId", "")
        if msg_id:
            id_to_line[msg_id] = i + 1
            id_to_parent[msg_id] = parent_id
            id_to_obj[msg_id] = obj

    # Pass 1: Find broken assistant messages with partialJson
    for msg_id, obj in id_to_obj.items():
        if is_aborted_with_partial(obj):
            remove_ids.add(msg_id)
            details.append(f"BROKEN ASSISTANT (partialJson): id={msg_id} line={id_to_line[msg_id]}")

            # Collect tool_use IDs from this broken message
            broken_tool_ids = set()
            for block in obj.get("message", {}).get("content", []):
                if block.get("type") == "toolCall":
                    broken_tool_ids.add(block.get("id", ""))

            if verbose:
                details.append(f"  Tool IDs in broken message: {broken_tool_ids}")

    # Pass 2: Find synthetic toolResults whose parent is a removed message
    for msg_id, obj in id_to_obj.items():
        parent = id_to_parent.get(msg_id, "")
        if parent in remove_ids and is_synthetic_tool_result(obj):
            remove_ids.add(msg_id)
            details.append(f"SYNTHETIC TOOL_RESULT: id={msg_id} line={id_to_line[msg_id]} parent={parent}")

    # Pass 3: Find cascading error responses
    for msg_id, obj in id_to_obj.items():
        if is_corrupted_error(obj):
            remove_ids.add(msg_id)
            details.append(f"ERROR RESPONSE (400): id={msg_id} line={id_to_line[msg_id]}")

    # Pass 4: Compute reparenting — any message whose parent was removed
    # Walk up the chain to find the nearest surviving ancestor
    seen = set()  # Cycle guard

    def find_surviving_ancestor(msg_id):
        visited = set()
        current = msg_id
        while current in remove_ids:
            if current in visited:
                return None  # Cycle detected
            visited.add(current)
            current = id_to_parent.get(current, "")
            if not current:
                return None
        return current

    for msg_id, obj in id_to_obj.items():
        if msg_id in remove_ids:
            continue
        parent = id_to_parent.get(msg_id, "")
        if parent in remove_ids:
            new_parent = find_surviving_ancestor(parent)
            if new_parent:
                reparent_map[msg_id] = new_parent
                details.append(f"REPARENT: id={msg_id} line={id_to_line[msg_id]} {parent} -> {new_parent}")

    return remove_ids, reparent_map, details, len(lines)


def fix_session(filepath, remove_ids, reparent_map, verbose=False):
    """Apply fixes to a session file."""
    with open(filepath) as f:
        lines = f.readlines()

    output_lines = []
    removed = 0
    reparented = 0

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            obj = json.loads(stripped)
        except json.JSONDecodeError:
            output_lines.append(stripped)
            continue

        msg_id = obj.get("id", "")

        if msg_id in remove_ids:
            removed += 1
            continue

        if msg_id in reparent_map:
            obj["parentId"] = reparent_map[msg_id]
            reparented += 1

        output_lines.append(json.dumps(obj, ensure_ascii=False))

    with open(filepath, "w") as f:
        for line in output_lines:
            f.write(line + "\n")

    return removed, reparented, len(output_lines)


def verify_session(filepath, verbose=False):
    """Post-fix verification: check no orphaned parents remain."""
    with open(filepath) as f:
        lines = f.readlines()

    all_ids = set()
    orphans = []

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            obj = json.loads(stripped)
            msg_id = obj.get("id", "")
            if msg_id:
                all_ids.add(msg_id)
        except:
            pass

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            obj = json.loads(stripped)
            parent = obj.get("parentId", "")
            msg_id = obj.get("id", "")
            if parent and parent not in all_ids:
                orphans.append((msg_id, parent))
        except:
            pass

    return orphans


def main():
    import argparse
    parser = argparse.ArgumentParser(description="Fix corrupted OpenClaw session transcripts")
    parser.add_argument("session_dir", nargs="?", default=DEFAULT_SESSION_DIR,
                        help="Session directory (default: ~/.openclaw/agents/main/sessions)")
    parser.add_argument("--fix", action="store_true", help="Apply the fix (default is dry-run)")
    parser.add_argument("--verbose", action="store_true", help="Verbose output")
    parser.add_argument("--all-agents", action="store_true", help="Scan all agents")
    parser.add_argument("--session-id", help="Target a specific session ID")
    args = parser.parse_args()

    session_dir = args.session_dir

    if args.all_agents:
        agents_dir = os.path.expanduser("~/.openclaw/agents")
        dirs = []
        for agent in os.listdir(agents_dir):
            sdir = os.path.join(agents_dir, agent, "sessions")
            if os.path.isdir(sdir):
                dirs.append(sdir)
    else:
        dirs = [session_dir]

    for sdir in dirs:
        print(f"\n{'='*60}")
        print(f"Scanning: {sdir}")
        print(f"{'='*60}")

        if args.session_id:
            files = [os.path.join(sdir, f"{args.session_id}.jsonl")]
        else:
            # Find active session
            active = find_active_session(sdir)
            if active:
                files = [os.path.join(sdir, f"{active}.jsonl")]
                print(f"Active session: {active}")
            else:
                files = sorted(Path(sdir).glob("*.jsonl"), key=lambda p: p.stat().st_mtime, reverse=True)
                files = [str(f) for f in files[:5]]  # Check 5 most recent
                print(f"No active session found, checking {len(files)} most recent files")

        for filepath in files:
            if not os.path.exists(filepath):
                print(f"  File not found: {filepath}")
                continue

            print(f"\n  File: {os.path.basename(filepath)}")
            try:
                remove_ids, reparent_map, details, total_lines = scan_session(filepath, args.verbose)
            except Exception as e:
                print(f"  ERROR scanning: {e}")
                continue

            if not remove_ids:
                print(f"  Status: CLEAN ({total_lines} lines)")
                continue

            print(f"  Status: CORRUPTED")
            print(f"  Lines to remove: {len(remove_ids)}")
            print(f"  References to reparent: {len(reparent_map)}")
            for d in details:
                print(f"    {d}")

            if args.fix:
                # Backup
                backup = f"{filepath}.bak.{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                shutil.copy2(filepath, backup)
                print(f"\n  Backup: {backup}")

                # Fix
                removed, reparented, final_lines = fix_session(filepath, remove_ids, reparent_map, args.verbose)
                print(f"  Fixed: removed {removed} lines, reparented {reparented} references")
                print(f"  Lines: {total_lines} -> {final_lines}")

                # Verify
                orphans = verify_session(filepath, args.verbose)
                if orphans:
                    print(f"  WARNING: {len(orphans)} orphaned parent references remain!")
                    for mid, pid in orphans[:5]:
                        print(f"    id={mid} -> missing parent {pid}")
                else:
                    print(f"  Verification: CLEAN")
            else:
                print(f"\n  Dry run — use --fix to apply")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""generate-problem-summary.py - Generate markdown summary of open/stuck Problems.

Reads problems.jsonl and outputs a markdown summary suitable for injection
into the agent's first turn after resurrection.

Usage:
  generate-problem-summary.py [--learning-dir DIR] [--output FILE]

If --output is provided, writes to that file. Otherwise prints to stdout.
"""

import argparse
import json
import os
import subprocess
import sys
from datetime import datetime, timezone
from urllib.request import Request, urlopen
from urllib.error import URLError


def get_workspace():
    oc_config = os.path.expanduser("~/.openclaw/openclaw.json")
    try:
        with open(oc_config) as f:
            data = json.load(f)
        ws = data.get("agents", {}).get("defaults", {}).get("workspace", "~/.openclaw/workspace")
    except (IOError, json.JSONDecodeError):
        ws = "~/.openclaw/workspace"
    return os.path.expanduser(ws)


def replay_problems(filepath):
    """Replay JSONL to reconstruct problem states."""
    states = {}
    if not os.path.isfile(filepath):
        return states
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            rid = record.get("id", "")
            op = record.get("op", "create")
            if op == "create":
                states[rid] = record.copy()
                states[rid].pop("op", None)
            elif op == "update" and rid in states:
                states[rid].update(record.get("fields", {}))
                states[rid]["updated"] = record.get("timestamp", "")
            elif op == "close" and rid in states:
                states[rid]["status"] = record.get("status", "solved")
                if record.get("solution"):
                    states[rid]["solution"] = record["solution"]
                states[rid]["resolved"] = record.get("timestamp", "")
    return states


def get_solvr_api_key():
    """Read SOLVR_API_KEY from env or config.json."""
    key = os.environ.get("SOLVR_API_KEY", "")
    if key:
        return key
    config_path = os.path.expanduser("~/.amcp/config.json")
    try:
        with open(config_path) as f:
            data = json.load(f)
        key = (data.get("solvr", {}).get("apiKey", "") or
               data.get("pinning", {}).get("solvr", {}).get("apiKey", ""))
    except (IOError, json.JSONDecodeError):
        pass
    return key


def should_surface_remote():
    """Check config toggle: solvr.surfaceRemoteProblems (default: true)."""
    config_path = os.path.expanduser("~/.amcp/config.json")
    try:
        with open(config_path) as f:
            data = json.load(f)
        return data.get("solvr", {}).get("surfaceRemoteProblems", True)
    except (IOError, json.JSONDecodeError):
        return True


def fetch_solvr_problems(api_key):
    """Fetch open problems from Solvr API (GET /v1/me/posts?type=problem&status=open)."""
    if not api_key:
        return []
    base = os.environ.get("SOLVR_BASE_URL", "https://api.solvr.dev/v1")
    url = f"{base}/me/posts?type=problem&status=open"
    try:
        req = Request(url, headers={
            "Authorization": f"Bearer {api_key}",
            "Accept": "application/json",
        })
        with urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode())
        posts = data.get("data", data if isinstance(data, list) else [])
        # Normalize to local problem format
        problems = []
        for p in posts:
            problems.append({
                "id": p.get("id", "?"),
                "description": p.get("title", p.get("description", "(no description)")),
                "status": p.get("status", "open"),
                "attempts": len(p.get("approaches", [])),
                "created": p.get("created_at", p.get("created", "unknown")),
                "source": "solvr",
            })
        return problems
    except (URLError, OSError, json.JSONDecodeError, KeyError) as e:
        print(f"WARN: Solvr fetch failed: {e}", file=sys.stderr)
        return []


def generate_summary(learning_dir, include_solvr=True):
    """Generate markdown summary of open/stuck problems."""
    problems_file = os.path.join(learning_dir, "problems.jsonl")
    states = replay_problems(problems_file)

    open_problems = [
        p for p in states.values()
        if p.get("status") in ("open", "stuck")
    ]

    # Merge Solvr remote problems (deduped by id)
    if include_solvr and should_surface_remote():
        api_key = get_solvr_api_key()
        solvr_problems = fetch_solvr_problems(api_key)
        local_ids = {p.get("id") for p in open_problems}
        for sp in solvr_problems:
            if sp["id"] not in local_ids:
                open_problems.append(sp)
                local_ids.add(sp["id"])

    if not open_problems:
        return ""

    # Sort by created (oldest first)
    open_problems.sort(key=lambda x: x.get("created", ""))

    lines = []
    lines.append(f"## Unresolved Problems ({len(open_problems)})")
    lines.append("")
    lines.append("You have unresolved problems from before recovery. "
                 "Review when appropriate — do NOT auto-attempt all at once.")
    lines.append("")

    for p in open_problems:
        pid = p.get("id", "?")
        desc = p.get("description", "(no description)")
        status = p.get("status", "open")
        attempts = p.get("attempts", 0)
        created = p.get("created", "unknown")
        source = p.get("source", "local")

        source_tag = " (Solvr)" if source == "solvr" else ""
        lines.append(f"- **{pid}** [{status}]{source_tag}: {desc}")
        if attempts > 0:
            lines.append(f"  - Attempts: {attempts}")
        lines.append(f"  - Created: {created[:10]}")

    lines.append("")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Generate markdown summary of open/stuck Problems"
    )
    parser.add_argument("--learning-dir", help="Learning storage directory")
    parser.add_argument("--output", "-o", help="Output file (default: stdout)")
    args = parser.parse_args()

    learning_dir = args.learning_dir or os.environ.get("LEARNING_DIR")
    if not learning_dir:
        learning_dir = os.path.join(get_workspace(), "memory", "learning")

    summary = generate_summary(learning_dir)

    if not summary:
        print("No open problems to surface.", file=sys.stderr)
        sys.exit(0)

    if args.output:
        os.makedirs(os.path.dirname(args.output) or ".", exist_ok=True)
        with open(args.output, "w") as f:
            f.write(summary)
        print(f"Problem summary written to {args.output}", file=sys.stderr)
    else:
        print(summary)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""learning-report.py - Generate human-readable learning metrics report.

Reads problems.jsonl, learnings.jsonl, and stats.json to produce a
report with: total problems, solve rate, avg attempts, self-improvement rate.

Usage:
  learning-report.py [--output FILE] [--learning-dir DIR] [--json]

Environment:
  LEARNING_DIR  Override learning storage directory
"""

import argparse, json, os, sys
from collections import Counter


def get_learning_dir():
    env_dir = os.environ.get("LEARNING_DIR")
    if env_dir:
        return os.path.expanduser(env_dir)
    oc_config = os.path.expanduser("~/.openclaw/openclaw.json")
    try:
        with open(oc_config) as f:
            ws = json.load(f).get("agents", {}).get("defaults", {}).get("workspace", "~/.openclaw/workspace")
    except (IOError, json.JSONDecodeError):
        ws = "~/.openclaw/workspace"
    return os.path.join(os.path.expanduser(ws), "memory", "learning")


def replay_jsonl(filepath):
    """Replay JSONL to reconstruct entity states -> {id: state}."""
    states = {}
    if not os.path.isfile(filepath):
        return states
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            rid, op = rec.get("id", ""), rec.get("op", "create")
            ts = rec.get("timestamp", "")
            if op == "create":
                states[rid] = rec.copy()
                states[rid].pop("op", None)
            elif op == "update" and rid in states:
                states[rid].update(rec.get("fields", {}))
                states[rid]["updated"] = ts
            elif op == "close" and rid in states:
                states[rid]["status"] = rec.get("status", "solved")
                if rec.get("solution"):
                    states[rid]["solution"] = rec["solution"]
                states[rid]["resolved"] = states[rid]["updated"] = ts
            elif op == "verify" and rid in states:
                states[rid].update(confidence="verified", verified_at=ts,
                                   human_verified=rec.get("human_verified", True), updated=ts)
    return states


def compute_metrics(learning_dir):
    """Compute detailed metrics from JSONL stores."""
    problems = replay_jsonl(os.path.join(learning_dir, "problems.jsonl"))
    learnings = replay_jsonl(os.path.join(learning_dir, "learnings.jsonl"))

    stats = {}
    stats_file = os.path.join(learning_dir, "stats.json")
    if os.path.isfile(stats_file):
        try:
            with open(stats_file) as f:
                stats = json.load(f)
        except (json.JSONDecodeError, IOError):
            pass

    by_status, by_source, total_attempts, solved = Counter(), Counter(), 0, 0
    for p in problems.values():
        st = p.get("status", "open")
        by_status[st] += 1
        total_attempts += p.get("attempts", 0)
        if st == "solved":
            solved += 1
            by_source[p.get("source", "unknown")] += 1

    by_confidence = Counter(l.get("confidence", "tentative") for l in learnings.values())
    total = len(problems)
    solved_post = stats.get("solved_post_recovery", 0)
    total_solved = stats.get("total_solved", solved)

    return {
        "total_problems": total, "total_learnings": len(learnings),
        "problems_by_status": dict(by_status),
        "learnings_by_confidence": dict(by_confidence),
        "problems_solved_by_source": dict(by_source),
        "solve_rate": round(solved / total * 100, 1) if total else 0,
        "avg_attempts_to_solve": round(total_attempts / solved, 1) if solved else 0,
        "solved_post_recovery": solved_post, "total_solved": total_solved,
        "self_improvement_rate": round(solved_post / total_solved * 100, 1) if total_solved else 0,
    }


def format_report(m):
    """Format metrics as human-readable markdown report."""
    sections = [
        "# Learning Report\n",
        "## Summary\n",
        f"- **Total problems:** {m['total_problems']}",
        f"- **Total learnings:** {m['total_learnings']}",
        f"- **Solve rate:** {m['solve_rate']}%",
        f"- **Avg attempts to solve:** {m['avg_attempts_to_solve']}",
        f"- **Self-improvement rate:** {m['self_improvement_rate']}% "
        f"({m['solved_post_recovery']}/{m['total_solved']} solved post-recovery)\n",
    ]
    for title, data in [("Problems by Status", m["problems_by_status"]),
                        ("Learnings by Confidence", m["learnings_by_confidence"]),
                        ("Problems Solved by Source", m["problems_solved_by_source"])]:
        sections.append(f"## {title}\n")
        if data:
            sections.extend(f"- {k}: {v}" for k, v in sorted(data.items()))
        else:
            sections.append("- (none)")
    sections.append("")
    return "\n".join(sections)


def main():
    parser = argparse.ArgumentParser(description="Generate learning metrics report")
    parser.add_argument("--output", help="Write report to file (default: stdout)")
    parser.add_argument("--learning-dir", help="Override learning directory")
    parser.add_argument("--json", action="store_true", help="Output raw JSON metrics")
    args = parser.parse_args()

    metrics = compute_metrics(args.learning_dir or get_learning_dir())
    output = json.dumps(metrics, indent=2) + "\n" if args.json else format_report(metrics)

    if args.output:
        os.makedirs(os.path.dirname(args.output) or ".", exist_ok=True)
        with open(args.output, "w") as f:
            f.write(output)
        print(f"Report written to {args.output}", file=sys.stderr)
    else:
        print(output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""prune-ontology.py - Typed pruning policy framework for ontology graph.

Reads per-entity-type retention rules from ~/.amcp/config.json and prunes
memory/ontology/graph.jsonl. Supports TTL (30d, 90d, 1y), conditional
expressions (status == 'done'), and relation stub preservation.

Usage:
  prune-ontology.py [--dry-run] [--config FILE] [--graph FILE]

Environment:
  CONFIG_FILE   Override config path (default: ~/.amcp/config.json)
  CONTENT_DIR   Override workspace (default: from openclaw.json)
"""

import argparse, json, os, re, sys
from datetime import datetime, timezone, timedelta


def get_config_path():
    return os.path.expanduser(os.environ.get("CONFIG_FILE", "~/.amcp/config.json"))


def get_graph_path():
    content_dir = os.environ.get("CONTENT_DIR")
    if not content_dir:
        oc = os.path.expanduser("~/.openclaw/openclaw.json")
        try:
            with open(oc) as f:
                content_dir = json.load(f).get("agents", {}).get("defaults", {}).get(
                    "workspace", "~/.openclaw/workspace")
        except (IOError, json.JSONDecodeError):
            content_dir = "~/.openclaw/workspace"
    return os.path.join(os.path.expanduser(content_dir), "memory", "ontology", "graph.jsonl")


def load_policies(config_path):
    """Load pruning.policies from config.json."""
    try:
        with open(config_path) as f:
            cfg = json.load(f)
        return cfg.get("pruning", {}).get("policies", {})
    except (IOError, json.JSONDecodeError):
        return {}


def parse_ttl(ttl_str):
    """Parse TTL string (30d, 90d, 1y, 2w, 4h) into timedelta."""
    if not ttl_str or ttl_str == "null":
        return None
    m = re.match(r'^(\d+)([hdwmy])$', str(ttl_str).strip())
    if not m:
        return None
    val, unit = int(m.group(1)), m.group(2)
    if unit == 'h':
        return timedelta(hours=val)
    if unit == 'd':
        return timedelta(days=val)
    if unit == 'w':
        return timedelta(weeks=val)
    if unit == 'm':
        return timedelta(days=val * 30)
    if unit == 'y':
        return timedelta(days=val * 365)
    return None


def parse_timestamp(ts_str):
    """Parse ISO timestamp string to datetime."""
    if not ts_str:
        return None
    try:
        return datetime.fromisoformat(ts_str.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None


def evaluate_condition(condition_str, entity, now):
    """Evaluate a simple condition expression against entity properties.

    Supports: field == 'value', field != 'value', updated < 90d
    Conjunctions with AND (all must match).
    """
    if not condition_str:
        return False

    clauses = re.split(r'\s+AND\s+', condition_str, flags=re.IGNORECASE)
    for clause in clauses:
        clause = clause.strip()
        if not clause:
            continue

        # Temporal comparison: field < TTL (e.g., "updated < 90d")
        m = re.match(r'^(\w+)\s*<\s*(\d+[hdwmy])$', clause)
        if m:
            field, ttl_str = m.group(1), m.group(2)
            ttl = parse_ttl(ttl_str)
            if ttl is None:
                return False
            val = entity.get(field) or entity.get("properties", {}).get(field)
            ts = parse_timestamp(str(val)) if val else None
            if ts is None:
                return False
            if now - ts < ttl:
                return False
            continue

        # Equality: field == 'value'
        m = re.match(r"^(\w+)\s*==\s*'([^']*)'$", clause)
        if m:
            field, expected = m.group(1), m.group(2)
            actual = entity.get(field) or entity.get("properties", {}).get(field, "")
            if str(actual) != expected:
                return False
            continue

        # Inequality: field != 'value'
        m = re.match(r"^(\w+)\s*!=\s*'([^']*)'$", clause)
        if m:
            field, expected = m.group(1), m.group(2)
            actual = entity.get(field) or entity.get("properties", {}).get(field, "")
            if str(actual) == expected:
                return False
            continue

        # Unknown clause — fail safe (don't prune)
        return False

    return True


def should_prune(entity, policy, now):
    """Check if entity should be pruned based on its type's policy."""
    # Conditional expression takes priority (even with ttl: null)
    prune_if = policy.get("prune_if")
    if prune_if:
        return evaluate_condition(prune_if, entity, now)

    # ttl: null means never prune by age
    ttl_val = policy.get("ttl")
    if ttl_val is None:
        return False

    ttl = parse_ttl(ttl_val)
    if ttl is not None:
        created = parse_timestamp(entity.get("created") or entity.get("updated", ""))
        if created and (now - created) > ttl:
            return True

    return False


def prune_graph(graph_path, policies, dry_run=False):
    """Apply pruning policies to graph.jsonl. Returns summary dict."""
    if not os.path.isfile(graph_path):
        print("ERROR: Graph file not found: " + graph_path, file=sys.stderr)
        return {"pruned": 0, "kept": 0, "error": "file_not_found"}

    now = datetime.now(timezone.utc)
    entities, relations, pruned_ids = [], [], set()
    lines = []

    with open(graph_path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                lines.append(line)
                continue

            if rec.get("type") == "entity":
                etype = rec.get("entity_type", "")
                policy = policies.get(etype, {})
                if policy and should_prune(rec, policy, now):
                    pruned_ids.add(rec.get("id"))
                else:
                    entities.append(rec)
                    lines.append(json.dumps(rec))
            elif rec.get("type") == "relation":
                relations.append(rec)
            else:
                lines.append(json.dumps(rec))

    # Process relations: preserve stubs or remove
    relation_stubs = []
    kept_relations = []
    for rel in relations:
        from_pruned = rel.get("from_id") in pruned_ids
        to_pruned = rel.get("to_id") in pruned_ids
        if from_pruned or to_pruned:
            # Check if relation's entity type policy has preserve_relations
            # Look up the pruned entity's type
            preserve = False
            for eid in [rel.get("from_id"), rel.get("to_id")]:
                if eid in pruned_ids:
                    # We need the entity_type, but it's already pruned
                    # Check all policies for preserve_relations
                    for etype, pol in policies.items():
                        if pol.get("preserve_relations"):
                            preserve = True
                            break
            if preserve:
                stub = rel.copy()
                stub["deleted_at"] = now.isoformat()
                relation_stubs.append(stub)
                lines.append(json.dumps(stub))
            # else: relation removed entirely
        else:
            kept_relations.append(rel)
            lines.append(json.dumps(rel))

    summary = {
        "pruned_entities": len(pruned_ids),
        "pruned_ids": sorted(pruned_ids),
        "kept_entities": len(entities),
        "kept_relations": len(kept_relations),
        "relation_stubs": len(relation_stubs),
    }

    if dry_run:
        summary["dry_run"] = True
        print(json.dumps(summary, indent=2))
        return summary

    # Write .pruned then atomic rename
    pruned_path = graph_path + ".pruned"
    with open(pruned_path, "w") as f:
        for line in lines:
            f.write(line + "\n")
    os.rename(pruned_path, graph_path)

    summary["dry_run"] = False
    print(json.dumps(summary, indent=2))
    return summary


def main():
    parser = argparse.ArgumentParser(description="Prune ontology graph by typed policies")
    parser.add_argument("--dry-run", action="store_true", help="Show what would be pruned")
    parser.add_argument("--config", help="Override config.json path")
    parser.add_argument("--graph", help="Override graph.jsonl path")
    args = parser.parse_args()

    config_path = args.config or get_config_path()
    graph_path = args.graph or get_graph_path()

    policies = load_policies(config_path)
    if not policies:
        print("No pruning policies configured in " + config_path, file=sys.stderr)
        print(json.dumps({"pruned_entities": 0, "kept_entities": 0, "message": "no_policies"}))
        sys.exit(0)

    prune_graph(graph_path, policies, dry_run=args.dry_run)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""temporal-queries.py - Cross-checkpoint entity history queries.

3-level temporal storage:
  Level 1: Current graph.jsonl (live entities)
  Level 2: Checkpoint snapshots in ~/.amcp/checkpoints/
  Level 3: Temporal index at ~/.amcp/memory/temporal-index.jsonl

Usage:
  temporal-queries.py history <entity_id>
  temporal-queries.py query <entity_id> --start YYYY-MM-DD --end YYYY-MM-DD
  temporal-queries.py build-index --graph <path> --cid <checkpoint_cid>

Environment:
  TEMPORAL_INDEX_PATH   Override temporal index location
  CONTENT_DIR           Override workspace path
"""
import argparse, hashlib, json, os, sys
from datetime import datetime, timezone

def _get_workspace():
    try:
        with open(os.path.expanduser("~/.openclaw/openclaw.json")) as f:
            return os.path.expanduser(json.load(f).get("agents",{}).get("defaults",{}).get("workspace","~/.openclaw/workspace"))
    except (IOError, json.JSONDecodeError):
        return os.path.expanduser("~/.openclaw/workspace")

CONTENT_DIR = os.environ.get("CONTENT_DIR", _get_workspace())
TEMPORAL_INDEX_PATH = os.environ.get("TEMPORAL_INDEX_PATH", os.path.expanduser("~/.amcp/memory/temporal-index.jsonl"))
GRAPH_PATH = os.path.join(CONTENT_DIR, "memory", "ontology", "graph.jsonl")

# ============================================================
# Level 1: Read current graph.jsonl
# ============================================================

def read_graph_entities(graph_path):
    """Read all non-relation entities from graph.jsonl."""
    entities = {}
    if not os.path.isfile(graph_path):
        return entities
    with open(graph_path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if record.get("type") == "relation":
                continue
            eid = record.get("id")
            if eid:
                entities[eid] = record
    return entities

# ============================================================
# Level 3: Temporal index operations
# ============================================================

def compute_version_hash(entity):
    """Deterministic hash of entity properties for change detection."""
    serialized = json.dumps(entity, sort_keys=True)
    return hashlib.sha256(serialized.encode()).hexdigest()[:16]

def build_index(graph_path, checkpoint_cid, timestamp=None):
    """Extract entities from graph.jsonl and append to temporal index."""
    if not os.path.isfile(graph_path):
        print(f"No graph at {graph_path}")
        return 0

    if timestamp is None:
        timestamp = datetime.now(timezone.utc).isoformat()

    entities = read_graph_entities(graph_path)
    if not entities:
        print("No entities in graph")
        return 0

    # Load existing index to check for unchanged entities
    existing = {}
    if os.path.isfile(TEMPORAL_INDEX_PATH):
        with open(TEMPORAL_INDEX_PATH) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    r = json.loads(line)
                    eid = r.get("entity_id", "")
                    if eid:
                        existing[eid] = r.get("version_hash", "")
                except json.JSONDecodeError:
                    continue

    os.makedirs(os.path.dirname(TEMPORAL_INDEX_PATH), exist_ok=True)
    added = 0
    with open(TEMPORAL_INDEX_PATH, "a") as f:
        for eid, entity in entities.items():
            vh = compute_version_hash(entity)
            # Skip if entity unchanged since last index entry
            if existing.get(eid) == vh:
                continue
            # Build compact snapshot
            snapshot = {}
            for k in ("name", "type", "description", "status", "labels"):
                if k in entity:
                    snapshot[k] = entity[k]
            props = entity.get("properties", {})
            if props:
                snapshot["properties"] = props

            entry = {
                "entity_id": eid,
                "checkpoint_cid": checkpoint_cid,
                "timestamp": timestamp,
                "version_hash": vh,
                "properties_snapshot": snapshot,
            }
            f.write(json.dumps(entry) + "\n")
            added += 1

    print(f"Indexed {added} entities (skipped {len(entities) - added} unchanged)")
    return added

# ============================================================
# Query functions
# ============================================================

def load_temporal_index(entity_id=None):
    """Load temporal index entries, optionally filtered by entity_id."""
    entries = []
    if not os.path.isfile(TEMPORAL_INDEX_PATH):
        return entries
    with open(TEMPORAL_INDEX_PATH) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if entity_id and r.get("entity_id") != entity_id:
                continue
            entries.append(r)
    return entries

def get_memory_history(entity_id):
    """Full evolution timeline for an entity across all checkpoints."""
    # Level 3: temporal index
    indexed = load_temporal_index(entity_id)

    # Level 1: current graph (if entity exists and differs from last indexed)
    current = read_graph_entities(GRAPH_PATH).get(entity_id)
    if current:
        current_vh = compute_version_hash(current)
        last_vh = indexed[-1]["version_hash"] if indexed else ""
        if current_vh != last_vh:
            indexed.append({
                "entity_id": entity_id,
                "checkpoint_cid": "current",
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "version_hash": current_vh,
                "properties_snapshot": current,
            })

    # Sort by timestamp
    indexed.sort(key=lambda x: x.get("timestamp", ""))
    return indexed

def query_by_time_range(entity_id, start_date, end_date):
    """Query entity versions within a time range."""
    history = get_memory_history(entity_id)
    results = []
    for entry in history:
        ts = entry.get("timestamp", "")
        # Compare date portion
        entry_date = ts[:10] if len(ts) >= 10 else ""
        if start_date and entry_date < start_date:
            continue
        if end_date and entry_date > end_date:
            continue
        results.append(entry)
    return results

# ============================================================
# CLI
# ============================================================

def cmd_history(args):
    history = get_memory_history(args.entity_id)
    if not history:
        print(f"No history found for entity: {args.entity_id}")
        return
    print(json.dumps(history, indent=2))

def cmd_query(args):
    results = query_by_time_range(args.entity_id, args.start, args.end)
    if not results:
        print(f"No results for {args.entity_id} in range [{args.start or '*'}, {args.end or '*'}]")
        return
    print(json.dumps(results, indent=2))

def cmd_build_index(args):
    ts = args.timestamp or datetime.now(timezone.utc).isoformat()
    build_index(args.graph, args.cid, ts)

def main():
    parser = argparse.ArgumentParser(description="Temporal query interface for entity history")
    sub = parser.add_subparsers(dest="command")

    p_hist = sub.add_parser("history", help="Full evolution timeline for an entity")
    p_hist.add_argument("entity_id", help="Entity ID to query")

    p_query = sub.add_parser("query", help="Query entity versions by time range")
    p_query.add_argument("entity_id", help="Entity ID to query")
    p_query.add_argument("--start", default="", help="Start date YYYY-MM-DD")
    p_query.add_argument("--end", default="", help="End date YYYY-MM-DD")

    p_build = sub.add_parser("build-index", help="Build temporal index from graph.jsonl")
    p_build.add_argument("--graph", required=True, help="Path to graph.jsonl")
    p_build.add_argument("--cid", required=True, help="Checkpoint CID")
    p_build.add_argument("--timestamp", default="", help="Checkpoint timestamp (ISO)")

    args = parser.parse_args()
    if args.command == "history":
        cmd_history(args)
    elif args.command == "query":
        cmd_query(args)
    elif args.command == "build-index":
        cmd_build_index(args)
    else:
        parser.print_help()
        sys.exit(1)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""validate-ontology.py - Schema validation for JSONL ontology graph files.

Validates graph.jsonl format and integrity:
- Each line is valid JSON with 'type' field (entity or relation)
- Entities have required fields: id, type, properties
- Relations have required fields: from_id, relation_type, to_id
- Relation integrity: from_id and to_id reference existing entities
- Acyclic check: 'blocks' relations must not form cycles

Output JSON:
  { "valid": true, "entity_count": N, "relation_count": M }
  { "valid": false, "errors": [...], "entity_count": N, "relation_count": M }

Usage:
  validate-ontology.py <graph.jsonl>
  validate-ontology.py --graph <path>
"""

import argparse
import json
import os
import sys
from collections import defaultdict


def load_and_validate(filepath):
    """Load graph.jsonl and validate each record."""
    entities = {}
    relations = []
    errors = []

    if not os.path.isfile(filepath):
        return {
            "valid": True,
            "entity_count": 0,
            "relation_count": 0,
            "skipped": True,
            "reason": "file not found",
        }

    with open(filepath) as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue

            # Valid JSON check
            try:
                record = json.loads(line)
            except json.JSONDecodeError as e:
                errors.append(f"line {lineno}: invalid JSON: {e}")
                continue

            if not isinstance(record, dict):
                errors.append(f"line {lineno}: expected object, got {type(record).__name__}")
                continue

            record_type = record.get("type")
            if not record_type:
                errors.append(f"line {lineno}: missing 'type' field")
                continue

            if record_type == "relation":
                # Validate relation fields
                missing = []
                for field in ("from_id", "relation_type", "to_id"):
                    if not record.get(field):
                        missing.append(field)
                if missing:
                    errors.append(
                        f"line {lineno}: relation missing fields: {', '.join(missing)}"
                    )
                else:
                    relations.append(
                        {
                            "lineno": lineno,
                            "from_id": record["from_id"],
                            "to_id": record["to_id"],
                            "relation_type": record["relation_type"],
                        }
                    )
            else:
                # Entity — validate required fields
                eid = record.get("id")
                if not eid:
                    errors.append(f"line {lineno}: entity missing 'id' field")
                    continue

                if "properties" not in record and not isinstance(
                    record.get("properties"), dict
                ):
                    # properties can be missing (backward compat) but should be dict if present
                    pass

                entities[eid] = lineno

    # Relation integrity: from_id and to_id must reference existing entities
    for rel in relations:
        if rel["from_id"] not in entities:
            errors.append(
                f"line {rel['lineno']}: relation from_id '{rel['from_id']}' "
                f"references non-existent entity"
            )
        if rel["to_id"] not in entities:
            errors.append(
                f"line {rel['lineno']}: relation to_id '{rel['to_id']}' "
                f"references non-existent entity"
            )

    # Acyclic check for 'blocks' relations
    blocks_graph = defaultdict(set)
    for rel in relations:
        if rel["relation_type"] == "blocks":
            blocks_graph[rel["from_id"]].add(rel["to_id"])

    if blocks_graph:
        cycle = detect_cycle(blocks_graph)
        if cycle:
            errors.append(
                f"circular dependency in 'blocks' relations: "
                f"{' -> '.join(cycle)}"
            )

    result = {
        "valid": len(errors) == 0,
        "entity_count": len(entities),
        "relation_count": len(relations),
    }
    if errors:
        result["errors"] = errors

    return result


def detect_cycle(graph):
    """Detect cycle in directed graph using DFS. Returns cycle path or None."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = defaultdict(int)
    parent = {}

    def dfs(node, path):
        color[node] = GRAY
        path.append(node)
        for neighbor in graph.get(node, set()):
            if color[neighbor] == GRAY:
                # Found cycle
                cycle_start = path.index(neighbor)
                return path[cycle_start:] + [neighbor]
            if color[neighbor] == WHITE:
                parent[neighbor] = node
                result = dfs(neighbor, path)
                if result:
                    return result
        path.pop()
        color[node] = BLACK
        return None

    for node in list(graph.keys()):
        if color[node] == WHITE:
            result = dfs(node, [])
            if result:
                return result

    return None


def main():
    parser = argparse.ArgumentParser(
        description="Validate ontology graph.jsonl schema and integrity"
    )
    parser.add_argument(
        "graph_path", nargs="?", help="Path to graph.jsonl"
    )
    parser.add_argument(
        "--graph", dest="graph_flag", help="Path to graph.jsonl (alternative)"
    )
    args = parser.parse_args()

    filepath = args.graph_path or args.graph_flag
    if not filepath:
        print(json.dumps({"valid": True, "entity_count": 0, "relation_count": 0,
                          "skipped": True, "reason": "no path provided"}))
        sys.exit(0)

    filepath = os.path.expanduser(filepath)
    result = load_and_validate(filepath)
    print(json.dumps(result, indent=2))

    if not result.get("valid", True) and not result.get("skipped"):
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""validate-skill-contract.py — Validate skill ontology contracts against graph.jsonl.

Reads contract from skill.json (ontologyContract field) or direct contract file.
Checks preconditions against current graph entities.

Called by validate-skill-contract.sh via environment variables:
  _CONTRACT_SOURCE  Path to skill.json or direct contract JSON
  _GRAPH_PATH       Path to graph.jsonl
  _JSON_OUTPUT      'true' for JSON output
  _SKILL_NAME       Skill name for display
  _IS_DIRECT_CONTRACT  'true' if contract source is a direct contract file
"""

import json
import os
import sys


def load_contract(source_path, is_direct):
    """Load ontologyContract from skill.json or direct file."""
    with open(source_path) as f:
        data = json.load(f)

    if is_direct:
        return data

    # Extract from skill.json
    return data.get("ontologyContract", {})


def load_graph(graph_path):
    """Load entities from graph.jsonl grouped by type."""
    entities_by_type = {}

    if not os.path.isfile(graph_path):
        return entities_by_type

    with open(graph_path) as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(record, dict):
                continue

            rtype = record.get("type")
            if rtype and rtype != "relation":
                if rtype not in entities_by_type:
                    entities_by_type[rtype] = []
                entities_by_type[rtype].append(record)

    return entities_by_type


def check_precondition(precond, entities_by_type):
    """Check a single precondition. Returns list of error strings."""
    errors = []
    parts = precond.split(".", 1)
    if len(parts) != 2:
        return [f"precondition '{precond}': invalid format (expected EntityType.property ...)"]

    etype = parts[0]
    rest = parts[1]
    entities = entities_by_type.get(etype, [])

    # No entities of this type = precondition trivially holds
    if not entities:
        return []

    if " exists" in rest:
        prop = rest.replace(" exists", "").strip()
        for entity in entities:
            props = entity.get("properties", {})
            if prop not in props:
                eid = entity.get("id", "unknown")
                errors.append(
                    f"precondition '{precond}': entity '{eid}' of type "
                    f"'{etype}' missing property '{prop}'"
                )

    elif " == " in rest:
        prop, expected = rest.split(" == ", 1)
        prop = prop.strip()
        expected = expected.strip().strip("'\"")
        for entity in entities:
            props = entity.get("properties", {})
            actual = props.get(prop)
            if actual is not None and str(actual) != expected:
                eid = entity.get("id", "unknown")
                errors.append(
                    f"precondition '{precond}': entity '{eid}' has "
                    f"{etype}.{prop}='{actual}', expected '{expected}'"
                )

    elif " != " in rest:
        prop, forbidden = rest.split(" != ", 1)
        prop = prop.strip()
        forbidden = forbidden.strip().strip("'\"")
        for entity in entities:
            props = entity.get("properties", {})
            actual = props.get(prop)
            if actual is not None and str(actual) == forbidden:
                eid = entity.get("id", "unknown")
                errors.append(
                    f"precondition '{precond}': entity '{eid}' has "
                    f"forbidden {etype}.{prop}='{actual}'"
                )

    elif " is valid enum" in rest:
        prop = rest.replace(" is valid enum", "").strip()
        for entity in entities:
            props = entity.get("properties", {})
            val = props.get(prop)
            if val is not None and not isinstance(val, str):
                eid = entity.get("id", "unknown")
                errors.append(
                    f"precondition '{precond}': entity '{eid}' has "
                    f"non-string {etype}.{prop}='{val}'"
                )
    else:
        errors.append(f"precondition '{precond}': unrecognized condition format")

    return errors


def main():
    source_path = os.environ.get("_CONTRACT_SOURCE", "")
    graph_path = os.path.expanduser(os.environ.get("_GRAPH_PATH", ""))
    json_output = os.environ.get("_JSON_OUTPUT", "false") == "true"
    skill_name = os.environ.get("_SKILL_NAME", "")
    is_direct = os.environ.get("_IS_DIRECT_CONTRACT", "") == "true"

    if not source_path or not os.path.isfile(source_path):
        result = {"valid": True, "skipped": True, "reason": "contract source not found"}
        if json_output:
            print(json.dumps(result, indent=2))
        else:
            print(f"SKIP: {skill_name or 'skill'} — contract source not found")
        sys.exit(0)

    try:
        contract = load_contract(source_path, is_direct)
    except (json.JSONDecodeError, KeyError) as e:
        result = {"valid": False, "errors": [f"Failed to load contract: {e}"]}
        if json_output:
            print(json.dumps(result, indent=2))
        else:
            print(f"FAIL: Could not load contract: {e}")
        sys.exit(1)

    # Empty contract = backward compatible skip
    if not contract or not contract.get("ontology"):
        result = {"valid": True, "skipped": True, "reason": "no ontology contract declared"}
        if json_output:
            print(json.dumps(result, indent=2))
        else:
            print(f"SKIP: {skill_name or 'skill'} has no ontology contract")
        sys.exit(0)

    ontology = contract["ontology"]
    reads = ontology.get("reads", [])
    writes = ontology.get("writes", [])
    preconditions = ontology.get("preconditions", [])

    entities_by_type = load_graph(graph_path)

    errors = []

    # Check reads: required entity types must exist
    for etype in reads:
        if etype not in entities_by_type:
            errors.append(f"reads '{etype}': no entities of type '{etype}' found in graph")

    # Check preconditions
    for precond in preconditions:
        errors.extend(check_precondition(precond, entities_by_type))

    result = {
        "valid": len(errors) == 0,
        "skill": skill_name or contract.get("skill_name", "unknown"),
        "reads": reads,
        "writes": writes,
        "preconditions_checked": len(preconditions),
        "entity_types_found": list(entities_by_type.keys()),
    }
    if errors:
        result["errors"] = errors

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        sname = result["skill"]
        if result["valid"]:
            print(f"PASS: {sname} — all {len(preconditions)} preconditions satisfied")
            print(f"  Reads: {', '.join(reads) or '(none)'}")
            print(f"  Writes: {', '.join(writes) or '(none)'}")
        else:
            print(f"FAIL: {sname} — {len(errors)} precondition violation(s)")
            for err in errors:
                print(f"  * {err}")

    sys.exit(0 if result["valid"] else 1)


if __name__ == "__main__":
    main()

